package com.projectseele.world;
import com.projectseele.entity.SiloHatchMechanism;
import com.projectseele.entity.SiloHatchMechanism.Spec;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.world.phys.*;

/** Actual selected source geometry and declared aperture only; no map/native claim. */
public final class NervSiloHatchGeometryR52Test
{
    private static int checks;
    private static void check(boolean b,String text){checks++;if(!b)throw new AssertionError(text);}
    private static JsonArray vector(double... values){var a=new JsonArray();for(double v:values)a.add(v);return a;}
    private static JsonArray box(AABB b){return vector(b.minX,b.minY,b.minZ,b.maxX,b.maxY,b.maxZ);}
    public static void main(String[] args)throws Exception
    {
        var assets=Path.of(args.length==0?"src/main/resources/assets/projectseele":args[0]);var legacy=new Spec(31,31,30,30);var spec=new Spec(164,164,120,180);var actual=NervSiloHatchGeometryR52.load(p->Files.readAllBytes(assets.resolve(p)),spec);
        for(int i=0;i<4;i++)for(float t:new float[]{0,.2F,.3F,.65F,1}){var old=SiloHatchMechanism.panel(i,t);var newPanel=SiloHatchMechanism.panel(i,t,legacy);check(Math.abs(old.x()-newPanel.x())<1e-12&&old.y()==newPanel.y(),"Original 31m panel channel stays unchanged");}
        var closed=actual.bounds(0);var open=actual.bounds(1);var union=closed.minmax(open);check(Math.abs(union.minX+103.825)<2e-6&&Math.abs(union.maxX-103.825)<2e-6,"Explicit 164m net aperture has measured 207.65m cassette/support extent rather than scaled 219m");check(Math.abs(union.minZ+83.895)<2e-6&&Math.abs(union.maxZ-83.8)<2e-6&&union.minY==-2.01&&Math.abs(union.maxY-5.695)<1e-6,"Source trim/tier thickness stays in original metres: "+union);
        var centre=new AABB(-1,.2,-1,1,.7,1);check(actual.intersects(RigidTransform.identity(),0,0,centre),"Closed original actual panel blocks the net opening");check(!actual.intersects(RigidTransform.identity(),1,1,new AABB(-82,-10,-82,82,10,82)),"All original panels/frame/supports physically clear the full 164 by 164 net hole when fully stacked");
        var midpoint=SiloHatchMechanism.panel(0,.65F,spec);var intermediate=new AABB(midpoint.x()+8,midpoint.y()+.2,-.1,midpoint.x()+8.1,midpoint.y()+.3,.1);check(!actual.intersects(RigidTransform.identity(),0,0,intermediate)&&!actual.intersects(RigidTransform.identity(),1,1,intermediate),"Middle-travel obstacle is absent from both stopped endpoint meshes");check(actual.intersects(RigidTransform.identity(),0,1,intermediate),"Certified lift-then-stack sweep catches that real intermediate obstacle");
        check(actual.bearingPoints().size()==8&&actual.bearingPoints().stream().allMatch(p->p.y==-2.01&&Math.abs(p.x)>82&&Math.abs(p.z)>82),"Actual cassette beams have eight explicit collar bearing points outside the aperture");
        var down=NervSiloHatchGeometryR52.load(p->Files.readAllBytes(assets.resolve(p)),new Spec(33,33,120,180,-1,-2.01));var downwardExtent=down.bounds(0).minmax(down.bounds(1));check(downwardExtent.getXsize()<42&&Math.abs(downwardExtent.getXsize()-41.75)<1e-6,"Actual compact service cassette fits the 42m original bay pitch");check(downwardExtent.minY< -5.69&&downwardExtent.maxY==1,"Actual downward tier cassettes and leaves remain below the closed floor datum");check(!down.intersects(RigidTransform.identity(),1,1,new AABB(-16.5,-10,-16.5,16.5,10,16.5)),"Downward full-open actual service panels and bearings clear the full net33 hole");check(down.bearingPoints().size()==8&&down.bearingPoints().stream().allMatch(p->Math.abs(-678.99+p.y+681)<1e-9),"Root explicit service frame bears exactly at foundation top -681");
        for(var p:down.bearingPoints()){int x=(int)Math.floor(p.x+.5),z=(int)Math.floor(p.z+.5);check(!down.intersects(RigidTransform.identity(),0,1,new AABB(x-.5,-6.01,z-.5,x+.5,-2.01,z+.5)),"A complete real revised four-block pillar stays clear of actual cassette and every leaf stroke");}
        for(var part:down.pieces(0))if(!part.moving())check(!down.movingIntersects(RigidTransform.identity(),.3F,1,new NervRigidMeshSweepR52(part.part().xyz()),part.local()),"Actual downward slide clears its fixed collar/cassette/bearing: "+part.part().name());
        var portedSpec=new Spec(33,33,120,180,-1,-2.01,true);var ported=NervSiloHatchGeometryR52.load(p->Files.readAllBytes(assets.resolve(p)),portedSpec);check(portedSpec.firstTier()==1.6&&Math.abs(portedSpec.maximumTier()-4.9)<1e-12,"Original column foot clearance has explicit 1.60/2.70/3.80/4.90m tiers");check(!ported.movingIntersects(RigidTransform.identity(),0,1,NervPlantMotionR52.originalFixedColumnsR52(),new RigidTransform(new Vec3(0,.03,0),0,0,0,1)),"The entire actual opening/closing curve clears all 4904 original fixed-column triangles through real source-derived foot ports");for(var part:ported.pieces(0))if(!part.moving())check(!ported.movingIntersects(RigidTransform.identity(),.3F,1,new NervRigidMeshSweepR52(part.part().xyz()),part.local()),"Actual column-ported slide clears every internal fixed part: "+part.part().name());
        var calibratedSpec=new Spec(33,33,120,180,-1,-2.02,true);var calibrated=NervSiloHatchGeometryR52.load(p->Files.readAllBytes(assets.resolve(p)),calibratedSpec);check(Math.abs(calibratedSpec.serviceColumnDatumOffsetY()-.02)<1e-12,"Final Root bearing calibration retains original gantry20mm above hatch datum");check(calibrated.bearingPoints().stream().allMatch(p->Math.abs(-678.98+p.y+681)<1e-9),"Final beam/frame calibration keeps every original native foundation top unchanged");check(!calibrated.movingIntersects(RigidTransform.identity(),0,1,NervPlantMotionR52.originalFixedColumnsR52(),new RigidTransform(new Vec3(0,.02,0),0,0,0,1)),"Final Root20mm gantry offset clears all4904 original columns throughout opening and closing");double sourceLeafTop=Double.NEGATIVE_INFINITY;for(var piece:calibrated.pieces(0))if(piece.moving())sourceLeafTop=Math.max(sourceLeafTop,new NervRigidMeshSweepR52(piece.part().xyz()).bounds().maxY);check(Math.abs(-678.98+sourceLeafTop+678)<.002,"Unchanged original source leaf now meets exact native floor within2mm without an added skin");
        var declared31=NervSiloHatchGeometryR52.load(p->Files.readAllBytes(assets.resolve(p)),new Spec(31,31,120,20,1,-2.02,false));check(declared31.bearingPoints().size()==8&&declared31.bearingPoints().stream().allMatch(p->Math.abs(.02+p.y+2)<1e-9),"Explicit R52 net31 has8 added beams bearing at exact integer floor-2");check(declared31.pieces(0).stream().filter(p->p.part().name().startsWith("bearing/")).count()==4,"Explicit31 renderer and collision share all4 physical cassette bearing beams");check(!declared31.intersects(RigidTransform.identity(),1,1,new AABB(-15.5,-10,-15.5,15.5,10,15.5)),"Added31 beams leave unchanged full-open original net31 opening clear");check(Math.abs(declared31.bounds(0).minY+2.02)<1e-9&&declared31.bounds(0).getXsize()<42,"Explicit31 grounded structure preserves42m shaft pitch");
        boolean rejectedDown31=false;try{new Spec(31,31,120,20,-1,-2.02,false);}catch(IllegalArgumentException unsupported){rejectedDown31=true;}check(rejectedDown31,"Unsupported explicitdown31 collar combination cannot commission or draw a conflicting mechanism");
        var output=new JsonObject();output.addProperty("schema","projectseele.r52.declared-silo-hatch-source-measurement.v1");output.addProperty("scope","Source measurement only; Root supplies frame, support cells, closed/open cells and commissioned world");output.addProperty("source_sha",NervSiloHatchGeometryR52.SOURCE_SHA);output.add("opening_xz",vector(164,164));output.add("all_static_and_moving_extents",box(union));var bearings=new JsonArray();for(var p:actual.bearingPoints())bearings.add(vector(p.x,p.y,p.z));output.add("mandatory_bearing_points_local",bearings);var rows=new JsonArray();for(float t:new float[]{0,.3F,.65F,1})for(var p:actual.pieces(t)){var row=new JsonObject();row.addProperty("progress",t);row.addProperty("part",p.part().name());row.addProperty("moving",p.moving());row.add("bounds",box(NervRigidMeshSweepR52.transformed(new NervRigidMeshSweepR52(p.part().xyz()).bounds(),p.local())));rows.add(row);}output.add("part_samples",rows);if(args.length>1)Files.writeString(Path.of(args[1]),new GsonBuilder().setPrettyPrinting().create().toJson(output));
        System.out.println("PASS R52 shared actual large hatch source/bearing/endpoint/full-curve checks: "+checks+" bounds="+union);
    }
}
